@namespace sv_38978cc4dc5a4cb0bfd705545cad8a80.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="mb-0">Position @Position</h6>
            @if (ShowRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input type="text" class="form-control" value="@Company"
                       @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input type="text" class="form-control" value="@Title"
                       @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => UpdateDate(true, e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       disabled="@IsCurrent"
                       @onchange="e => UpdateDate(false, e.Value?.ToString())" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Position { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        var data = BuildData();
        data = field switch
        {
            nameof(Company) => data with { Company = value ?? "" },
            nameof(Title) => data with { Title = value ?? "" },
            nameof(Description) => data with { Description = value ?? "" },
            _ => data
        };
        OnChanged.InvokeAsync(data);
    }

    private void UpdateDate(bool isStart, string? value)
    {
        var data = BuildData();
        if (DateTime.TryParse(value, out var date))
        {
            data = isStart ? data with { StartDate = date } : data with { EndDate = date };
        }
        OnChanged.InvokeAsync(data);
    }

    private void ToggleCurrent(bool current)
    {
        var data = BuildData() with { IsCurrent = current, EndDate = current ? null : EndDate };
        OnChanged.InvokeAsync(data);
    }

    private WorkEntryData BuildData() => new(Company, Title, StartDate, EndDate, IsCurrent, Description);

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

