+    private HashSet<int> _completedSteps = new();
+
+    // Step 1 state
+    private string _fullName = "";
+    private string _email = "";
+    private string _phone = "";
+    private string _address = "";
+
+    // Step 2 state
+    private List<WorkHistoryStep.EntryModel> _workEntries = new() { new() };
+
+    // Step 3 state
+    private List<ReferencesStep.RefModel> _references = new() { new(), new() };
+
+    // Step 4 state
+    private string _coverLetter = "";
+
+    private async Task HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        var isValid = await ApplicationService.ValidateEmailAsync(result.Email);
+        if (!isValid)
+        {
+            // Re-render will show error via the component's own state
+            // We need to pass error back - for simplicity we handle inline
+            return;
+        }
+
+        _fullName = result.FullName;
+        _email = result.Email;
+        _phone = result.Phone;
+        _address = result.Address;
+        _completedSteps.Add(0);
+        _currentStep = 1;
+    }
+
+    private Task HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
+    {
+        _workEntries = entries;
+        _completedSteps.Add(1);
+        _currentStep = 2;
+        return Task.CompletedTask;
+    }
+
+    private Task HandleReferencesNext(List<ReferencesStep.RefModel> refs)
+    {
+        _references = refs;
+        _completedSteps.Add(2);
+        _currentStep = 3;
+        return Task.CompletedTask;
+    }
+
+    private Task HandleCoverLetterNext(string coverLetter)
+    {
+        _coverLetter = coverLetter;
+        _completedSteps.Add(3);
+        _currentStep = 4;
+        return Task.CompletedTask;
+    }
+
+    private void HandleSubmitted(int applicationId)
+    {
+        _completedSteps.Add(4);
+    }
+
+    private void GoToStep(int step)
+    {
+        _currentStep = step;
+    }
+
+    private PersonalInfo BuildPersonalInfo() => new(_fullName, _email, _phone, _address);
+
+    private List<WorkEntry> BuildWorkEntries() => _workEntries.Select(e =>
+        new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
+
+    private List<Reference> BuildReferences() => _references.Select(r =>
+        new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+}
